import sys
from itertools import combinations

data = sys.stdin.read().split()
n, m, a, b = int(data[0]), int(data[1]), int(data[2]), int(data[3])
edges = [(int(data[4 + 2 * i]), int(data[5 + 2 * i])) for i in range(m)]
inc = [i for i, (u, v) in enumerate(edges) if v == b]

def reach(removed):
    adj = [[] for _ in range(n + 1)]
    for i, (u, v) in enumerate(edges):
        if i not in removed:
            adj[u].append(v)
    seen = {a}
    stack = [a]
    while stack:
        u = stack.pop()
        for v in adj[u]:
            if v not in seen:
                seen.add(v)
                stack.append(v)
    return b in seen

ans = None
for r in range(len(inc) + 1):
    for comb in combinations(inc, r):
        if not reach(set(comb)):
            ans = r
            break
    if ans is not None:
        break
print(ans)

